(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-792":{scenario:{company:"Công ty Lữ hành Mây Bạc",supervisor:{name:"Kiều Đức Thịnh",role:{vi:"Giám đốc Điều hành Tour",en:"Head of Tour Operations"}},ref_code:"TO-5126",title:{vi:"Đúng loại phòng. Đúng giá thành. Đúng xe an toàn.",en:"Right room type. Right cost. Safe vehicles."},brief:{vi:"Bạn chốt hồ sơ điều hành TO-5126: đoàn inbound 20 khách trả tiền và 1 trưởng đoàn miễn phí (FOC), tour Hà Nội - Hạ Long 3 ngày 2 đêm. Chi phí cố định: xe 18.000.000 đồng, hướng dẫn viên 4.500.000 đồng; chi phí theo đầu người 3.500.000 đồng gồm khách sạn, ăn, vé. Hai khách nam là đồng nghiệp ở chung và yêu cầu ngủ giường riêng. Sửa loại phòng trên danh sách phòng và giá thành mỗi khách trả tiền (số liệu mô phỏng), rồi lập báo cáo.",en:"You are closing operations file TO-5126: an inbound group of 20 paying guests plus 1 free tour leader (FOC) on a 3-day, 2-night Hanoi - Ha Long tour. Fixed costs: coach 18,000,000 VND, guide 4,500,000 VND; per-person cost 3,500,000 VND for hotel, meals and tickets. Two male colleagues share a room and want separate beds. Correct the room type on the rooming list and the cost per paying guest (training figures), then write a report."},reference_title:{vi:"Danh sách phòng & bảng giá thành đã duyệt · TO-5126",en:"Approved rooming list & costing sheet · TO-5126"},fields:[{id:"ROOM_TYPE",label:{vi:"Loại phòng của hai khách nam",en:"Room type for the two male guests"},initial:"DBL",expected:"TWN",choices:["SGL","DBL","TWN"],reference:"Danh sách phòng đã duyệt",hint:{vi:"Hai khách ở chung nhưng ngủ giường riêng cần phòng hai giường đơn, không phải phòng một giường đôi.",en:"Two guests sharing with separate beds need a room with two single beds, not one double bed."}},{id:"COST_PAX",label:{vi:"Giá thành mỗi khách trả tiền (VND)",en:"Cost per paying guest (VND)"},initial:"4625000",expected:"4800000",reference:"Bảng tính giá thành tour",ref_value:{vi:"Cố định 22.500.000 đồng; theo đầu người 3.500.000 đồng; 20 khách trả tiền + 1 FOC",en:"Fixed 22,500,000 VND; per person 3,500,000 VND; 20 paying guests + 1 FOC"},hint:{vi:"Chi phí theo đầu người của trưởng đoàn FOC vẫn phát sinh và phải phân bổ cho khách trả tiền.",en:"The FOC leader still incurs per-person costs, which must be spread over the paying guests."}}],sop32:{vi:"Giá thành mỗi khách trả tiền = (tổng chi phí cố định + chi phí theo đầu người x (số khách trả tiền + số FOC)) / số khách trả tiền (số liệu mô phỏng).",en:"Cost per paying guest = (total fixed costs + per-person cost x (paying guests + FOC)) / paying guests (training figures)."},context:{label:"TOUR OPS / TO-5126",metrics:[{label:{vi:"Khách trả tiền + FOC",en:"Paying guests + FOC"},value:"20 + 1"},{label:{vi:"Chi phí cố định",en:"Fixed costs"},value:"22,500,000 VND"},{label:{vi:"Chi phí mỗi người",en:"Per-person cost"},value:"3,500,000 VND"}]},crisis:{vi:"Nhà xe quen báo xe 29 chỗ cho đoàn sắp hết hạn kiểm định và chưa có phù hiệu xe du lịch nhưng giảm 3.000.000 đồng. Trưởng phòng nhắn: “Cứ dùng, đi 3 ngày không ai kiểm tra đâu, tiết kiệm được cho tour.”",en:"A familiar coach company says the 29-seat coach is about to fail its inspection date and has no tourist vehicle badge, but offers 3,000,000 VND off. Your manager writes: “Use it, nobody checks on a 3-day trip, it saves money.”"},options:{safe:{vi:"Không dùng xe không đủ điều kiện; báo Giám đốc Điều hành Tour, chọn nhà xe có kiểm định và phù hiệu hợp lệ trong danh sách đã thẩm định, ghi nhận chênh lệch vào giá thành.",en:"Do not use a non-compliant vehicle; inform the Head of Tour Operations, book an approved operator with valid inspection and badge, and record the cost difference."},shortcut:{vi:"Dùng xe giá rẻ cho kịp lịch và dặn tài xế tránh các trạm kiểm tra.",en:"Use the cheap coach to keep the schedule and tell the driver to avoid checkpoints."},wait:{vi:"Chưa đặt xe nào, chờ trưởng phòng tự xử lý sát ngày khởi hành.",en:"Book nothing and wait for the manager to sort it out close to departure."}},questions:{vi:["Vì sao bạn đổi loại phòng trên danh sách phòng? Yêu cầu nào của khách chứng minh lựa chọn đó?","Trình bày cách tính giá thành mỗi khách khi có FOC và cách xử lý khi nhà cung cấp vận chuyển không đủ điều kiện pháp lý."],en:["Why did you change the room type on the rooming list? Which guest request supports your choice?","Explain how you calculated the cost per guest with an FOC and how you handle a transport supplier that is not legally compliant."]},hints:{vi:["Đọc lại yêu cầu đặc biệt của khách trên phiếu đăng ký trước khi chọn mã loại phòng.","Theo SOP mục 3.2: tính đủ chi phí theo đầu người cho cả FOC rồi mới chia cho khách trả tiền.","Đọc lại SOP mục 4.2: chỉ dùng nhà cung cấp đủ điều kiện pháp lý và an toàn, mọi ngoại lệ phải báo cáo."],en:["Re-read the guests' special requests on the booking form before choosing the room type code.","Per SOP 3.2: include per-person costs for the FOC as well, then divide by paying guests.","Re-read SOP 4.2: use only legally compliant and safe suppliers; any exception must be escalated."]}},learning:{summary:{vi:"Chuyên viên điều hành tour quốc tế biến chương trình đã bán thành chuỗi dịch vụ chạy đúng giờ: đặt và xác nhận khách sạn, xe, nhà hàng, vé tham quan, hướng dẫn viên, vé máy bay; lập danh sách phòng, voucher, giá thành và theo dõi đoàn trong suốt hành trình. Với tour inbound, chuyên viên làm việc với đối tác nước ngoài; với tour outbound, chuyên viên lo thêm thị thực, bảo hiểm và đối tác tại điểm đến. Nghề đòi hỏi chi tiết, tính toán chính xác và phản ứng nhanh với sự cố.",en:"A tour operations specialist turns a sold programme into services that run on time: booking and confirming hotels, coaches, restaurants, tickets, guides and flights; preparing rooming lists, vouchers and costings; and following the group throughout the trip. Inbound work involves foreign partners; outbound work adds visas, insurance and destination partners. The role requires attention to detail, accurate costing and fast incident response."},responsibilities:{vi:["Đặt, xác nhận và theo dõi hạn hủy của khách sạn, xe, nhà hàng, vé tham quan, hướng dẫn viên.","Lập danh sách phòng, voucher dịch vụ và lịch trình chi tiết gửi đối tác, hướng dẫn viên.","Tính giá thành, kiểm soát chi phí thực tế so với dự toán và quyết toán sau tour.","Thẩm định nhà cung cấp về pháp lý, an toàn và chất lượng dịch vụ.","Trực sự cố 24/7, xử lý thay đổi lịch trình và báo cáo cho khách hàng, đối tác."],en:["Book, confirm and track cancellation deadlines for hotels, coaches, restaurants, tickets and guides.","Prepare rooming lists, service vouchers and detailed itineraries for partners and guides.","Calculate costings, control actual costs against budget and settle accounts after the tour.","Vet suppliers for legal compliance, safety and service quality.","Run a 24/7 incident line, handle itinerary changes and report to clients and partners."]},competencies:[{name:{vi:"Tính giá thành tour",en:"Tour costing"},desc:{vi:"Tách chi phí cố định, chi phí theo đầu người, phân bổ FOC và kiểm soát biên lợi nhuận.",en:"Separate fixed and per-person costs, allocate FOC and protect the margin."}},{name:{vi:"Quản lý đặt dịch vụ",en:"Service booking control"},desc:{vi:"Theo dõi allotment, hạn trả phòng, điều khoản hủy và xác nhận bằng văn bản.",en:"Track allotments, release dates, cancellation terms and written confirmations."}},{name:{vi:"Chính xác chi tiết",en:"Detail accuracy"},desc:{vi:"Kiểm tra tên khách, loại phòng, giờ bay, giờ đón khớp giữa các chứng từ.",en:"Check names, room types, flight and pick-up times match across documents."}},{name:{vi:"Quản lý nhà cung cấp",en:"Supplier management"},desc:{vi:"Thẩm định giấy phép, kiểm định, bảo hiểm và đánh giá chất lượng sau mỗi đoàn.",en:"Verify licences, inspections and insurance and rate quality after each group."}},{name:{vi:"Ứng phó sự cố",en:"Incident response"},desc:{vi:"Giữ bình tĩnh, ưu tiên an toàn khách, đưa phương án thay thế và thông tin rõ ràng.",en:"Stay calm, put guest safety first, offer alternatives and communicate clearly."}}],knowledge:{vi:["Luật Du lịch số 09/2017/QH14 về kinh doanh dịch vụ lữ hành nội địa, quốc tế và ký quỹ.","Nghị định 168/2017/NĐ-CP quy định chi tiết một số điều của Luật Du lịch.","Quy định hiện hành về kinh doanh vận tải khách du lịch bằng ô tô: phù hiệu, kiểm định, thời gian lái xe.","Điều khoản hợp đồng dịch vụ: allotment, hạn trả phòng, điều khoản hủy, chính sách FOC.","Bảo hiểm du lịch và quy trình xử lý khủng hoảng khi khách gặp sự cố trong nước và ở nước ngoài."],en:["Tourism Law No. 09/2017/QH14 on domestic and international travel services and deposits.","Decree 168/2017/ND-CP detailing several articles of the Tourism Law.","Current rules on tourist transport by car: badges, inspections and driving hours.","Service contract terms: allotments, release dates, cancellation terms and FOC policies.","Travel insurance and crisis procedures when guests face incidents at home or abroad."]},tools:["Phần mềm điều hành tour","Hệ thống đặt chỗ toàn cầu (GDS)","Bảng tính giá thành tour","Bảng điều phối xe và hướng dẫn viên","Kênh nhắn tin trực sự cố"],kpis:{vi:["Tỷ lệ dịch vụ được xác nhận bằng văn bản trước hạn.","Số phàn nàn do lỗi điều hành mỗi đoàn (mục tiêu bằng 0).","Chênh lệch giữa giá thành thực tế và dự toán.","Thời gian phản hồi sự cố trong hành trình."],en:["Share of services confirmed in writing before the deadline.","Complaints caused by operations errors per group (target zero).","Variance between actual and budgeted cost.","Response time to incidents during the tour."]},day:[{time:"08:00",vi:"Kiểm tra email đối tác, xác nhận dịch vụ còn treo và hạn trả phòng trong tuần.",en:"Check partner emails, chase pending confirmations and this week's release dates."},{time:"10:00",vi:"Lập danh sách phòng, voucher và lịch trình chi tiết cho đoàn sắp khởi hành.",en:"Prepare the rooming list, vouchers and detailed itinerary for an upcoming group."},{time:"13:30",vi:"Tính giá thành cho báo giá mới, đối chiếu đơn giá với hợp đồng nhà cung cấp.",en:"Cost a new quotation and check unit prices against supplier contracts."},{time:"15:30",vi:"Họp nhanh với hướng dẫn viên, bàn giao hồ sơ đoàn và số liên lạc khẩn cấp.",en:"Brief the guide, hand over the group file and emergency contacts."},{time:"17:30",vi:"Theo dõi các đoàn đang chạy, cập nhật nhật ký sự cố và bàn giao trực đêm.",en:"Monitor running groups, update the incident log and hand over to the night duty."}],mistakes:{vi:["Nhầm phòng hai giường đơn (TWN) với phòng một giường đôi (DBL) trên danh sách phòng.","Quên chi phí theo đầu người của FOC khiến giá thành thấp hơn thực tế.","Dùng nhà cung cấp rẻ nhưng thiếu giấy phép, kiểm định hoặc bảo hiểm."],en:["Confusing twin (TWN) and double (DBL) rooms on the rooming list.","Forgetting the FOC's per-person costs so the costing is too low.","Using a cheap supplier without licences, inspection or insurance."]},career:[{vi:"Nhân viên điều hành tour",en:"Tour operations assistant"},{vi:"Chuyên viên điều hành tour quốc tế",en:"Tour operations specialist"},{vi:"Trưởng nhóm điều hành inbound hoặc outbound",en:"Inbound or outbound operations lead"},{vi:"Giám đốc Điều hành Tour",en:"Head of tour operations"}],glossary:[{term:"FOC",vi:"Suất miễn phí nhà cung cấp hoặc công ty dành cho trưởng đoàn theo số khách trả tiền.",en:"Free of charge place given to a tour leader based on the number of paying guests."},{term:"Rooming list",vi:"Danh sách phân phòng gồm tên khách, loại phòng, ngày đến, ngày đi và yêu cầu đặc biệt.",en:"List of guest names, room types, arrival and departure dates and special requests."},{term:"Allotment",vi:"Số phòng khách sạn giữ cho công ty lữ hành theo hợp đồng trong một khoảng thời gian.",en:"Block of hotel rooms held for a tour operator under contract for a period."},{term:"Release date",vi:"Hạn trả lại phòng chưa dùng trong allotment mà không bị phạt.",en:"Deadline to return unused allotment rooms without penalty."},{term:"Voucher",vi:"Phiếu dịch vụ xác nhận khách được sử dụng dịch vụ đã đặt và thanh toán.",en:"Service document confirming the guest may use a booked and paid service."}],quiz:[{q:{vi:"Đoàn 15 khách trả tiền và 1 FOC; chi phí cố định 10.000.000 đồng, chi phí theo đầu người 2.000.000 đồng. Giá thành mỗi khách trả tiền là bao nhiêu?",en:"A group has 15 paying guests and 1 FOC; fixed costs 10,000,000 VND and per-person cost 2,000,000 VND. What is the cost per paying guest?"},options:{vi:["2.625.000 đồng","2.800.000 đồng","2.666.667 đồng","2.733.333 đồng"],en:["2,625,000 VND","2,800,000 VND","2,666,667 VND","2,733,333 VND"]},answer:1,explain:{vi:"(10.000.000 + 2.000.000 x 16) / 15 = 42.000.000 / 15 = 2.800.000 đồng.",en:"(10,000,000 + 2,000,000 x 16) / 15 = 42,000,000 / 15 = 2,800,000 VND."}},{q:{vi:"Mã phòng TWN trên danh sách phòng nghĩa là gì?",en:"What does the TWN room code mean on a rooming list?"},options:{vi:["Phòng một giường đôi","Phòng một giường đơn","Phòng ba giường","Phòng hai giường đơn riêng"],en:["One double bed","One single bed","Three beds","Two separate single beds"]},answer:3,explain:{vi:"TWN là phòng hai giường đơn riêng; DBL là phòng một giường đôi cho hai người.",en:"TWN is a room with two separate single beds; DBL is one double bed for two people."}},{q:{vi:"Xe đặt cho đoàn chưa có phù hiệu và sắp hết hạn kiểm định nhưng rẻ hơn. Bạn làm gì?",en:"The coach booked for a group has no badge and its inspection is expiring, but it is cheaper. What do you do?"},options:{vi:["Dùng xe vì tiết kiệm chi phí","Dùng xe nhưng dặn tài xế đi chậm","Đổi sang nhà xe đủ điều kiện và báo cấp trên","Để hướng dẫn viên tự quyết"],en:["Use it to save money","Use it but tell the driver to go slowly","Switch to a compliant operator and inform your manager","Let the guide decide"]},answer:2,explain:{vi:"An toàn khách và tuân thủ pháp luật vận tải được đặt trước chi phí; chênh lệch phải được ghi nhận minh bạch.",en:"Guest safety and transport compliance come before cost; the price difference must be recorded transparently."}},{q:{vi:"Release date trong hợp đồng allotment với khách sạn là gì?",en:"What is the release date in a hotel allotment contract?"},options:{vi:["Hạn trả lại phòng chưa dùng mà không bị phạt","Ngày khách nhận phòng","Ngày thanh toán cuối cùng","Ngày ký hợp đồng"],en:["Deadline to return unused rooms without penalty","Guest check-in date","Final payment date","Contract signing date"]},answer:0,explain:{vi:"Sau release date, phòng chưa trả lại có thể bị tính phí theo điều khoản hợp đồng.",en:"After the release date, unreturned rooms may be charged under the contract terms."}}],tools_en:["Tour operations software","Global distribution system (GDS)","Tour costing spreadsheets","Vehicle and tour guide dispatch board","Incident response messaging channel"]}}})})(window.KKR);
